INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G7.FOUNDA.INTRODUCTION_TO_CREATIVE.CA_CATEGORIES', 'CREA.G7.FOUNDA.INTRODUCTION_TO_CREATIVE', 'creative_arts', 7, 'Name the categories of Creative Arts and Sports and how they relate', ARRAY['CREA.G7.FOUNDA.INTRODUCTION_TO_CREATIVE.a', 'CREA.G7.FOUNDA.INTRODUCTION_TO_CREATIVE.b']::text[], 'The child names the categories (art and craft, music, physical education and sports, and performing arts such as drama and dance) and says they work together, for example music with dance and drama. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G7.RUBRIC.1.1), never as a phone question: c) make a collage on the categories of the Creative Arts and Sports.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G7.FOUNDA.COMPONENTS_OF_CREATIVE_A.STORY_ELEMENTS', 'CREA.G7.FOUNDA.COMPONENTS_OF_CREATIVE_A', 'creative_arts', 7, 'Name the elements of a story', ARRAY['CREA.G7.FOUNDA.COMPONENTS_OF_CREATIVE_A.a']::text[], 'The child names characters, setting, plot and theme as elements of a story, and says the setting is where and when it happens. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G7.FOUNDA.COMPONENTS_OF_CREATIVE_A.FITNESS_COMPONENTS', 'CREA.G7.FOUNDA.COMPONENTS_OF_CREATIVE_A', 'creative_arts', 7, 'Name the components of fitness', ARRAY['CREA.G7.FOUNDA.COMPONENTS_OF_CREATIVE_A.b']::text[], 'The child names health-related components (cardiovascular endurance, muscular strength, muscular endurance, flexibility, body composition) and skill-related ones (agility, balance, coordination, power, speed, reaction time). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G7.RUBRIC.1.1), never as a phone question: b) perform activities demonstrating the components of fitness.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G7.FOUNDA.COMPONENTS_OF_CREATIVE_A.NOTE_VALUES', 'CREA.G7.FOUNDA.COMPONENTS_OF_CREATIVE_A', 'creative_arts', 7, 'Read note values and group notes in 2 time', ARRAY['CREA.G7.FOUNDA.COMPONENTS_OF_CREATIVE_A.c', 'CREA.G7.FOUNDA.COMPONENTS_OF_CREATIVE_A.e']::text[], 'The child says a semibreve is 4 beats, a minim 2, a crotchet 1 and a quaver half a beat, and that a bar in 2 time (two crotchet beats) holds the value of two crotchets. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G7.FOUNDA.COMPONENTS_OF_CREATIVE_A.TREBLE_PITCHES', 'CREA.G7.FOUNDA.COMPONENTS_OF_CREATIVE_A', 'creative_arts', 7, 'Name pitches on the treble staff', ARRAY['CREA.G7.FOUNDA.COMPONENTS_OF_CREATIVE_A.d']::text[], 'The child says the lines of the treble staff from the bottom are E G B D F and the spaces are F A C E, and names a note by its place. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G7.CREATI.DRAWING_AND_PAINTING.BALANCE', 'CREA.G7.CREATI.DRAWING_AND_PAINTING', 'creative_arts', 7, 'Tell how balance works in a picture', ARRAY['CREA.G7.CREATI.DRAWING_AND_PAINTING.a']::text[], 'The child says balance is the even spread of visual weight in a picture, and names symmetrical (both sides alike), asymmetrical (different but equal in weight) and radial (spreading from the centre) balance. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G7.RUBRIC.2.1, CREA.G7.RUBRIC.2.2, CREA.G7.RUBRIC.2.3), never as a phone question: b) draw a picture to apply balance.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G7.CREATI.DRAWING_AND_PAINTING.COLOUR_TEMP', 'CREA.G7.CREATI.DRAWING_AND_PAINTING', 'creative_arts', 7, 'Tell warm colours from cool colours', ARRAY['CREA.G7.CREATI.DRAWING_AND_PAINTING.c']::text[], 'The child says red, orange and yellow are warm colours (like fire and sun) and blue, green and violet are cool (like water and sky), and says warm colours seem to come forward. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G7.RUBRIC.2.1, CREA.G7.RUBRIC.2.2, CREA.G7.RUBRIC.2.3), never as a phone question: d) paint a scenery based on colour temperature.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G7.CREATI.RHYTHM.RHYTHM_FACTORS', 'CREA.G7.CREATI.RHYTHM', 'creative_arts', 7, 'Name the factors in making a rhythm in simple time', ARRAY['CREA.G7.CREATI.RHYTHM.a']::text[], 'The child says a rhythm pattern depends on the time signature, the number of bars, the note values and rests, and that the beats in each bar must add up. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G7.RUBRIC.2.1, CREA.G7.RUBRIC.2.2, CREA.G7.RUBRIC.2.3), never as a phone question: b) compose a four- bar rhythmic pattern in 2 time, 4; c) write rhythmic patterns in 2 on monotone from 4 dictation; d) sight read rhythmic patterns on monotone.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G7.CREATI.JAVELIN_AND_SCULPTURE.JAVELIN', 'CREA.G7.CREATI.JAVELIN_AND_SCULPTURE', 'creative_arts', 7, 'Name materials for carving and the phases of a javelin throw', ARRAY['CREA.G7.CREATI.JAVELIN_AND_SCULPTURE.a', 'CREA.G7.CREATI.JAVELIN_AND_SCULPTURE.d']::text[], 'The child names carving materials (soft wood, bamboo) and the throwing phases in order (grip and carry, approach run, cross-step, delivery, recovery), and says a javelin is thrown only with a teacher in a cleared field. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G7.RUBRIC.2.1, CREA.G7.RUBRIC.2.2, CREA.G7.RUBRIC.2.3), never as a phone question: b) carve a javelin according to the right specification; c) decorate the javelin using appropriate techniques; d) perform a javelin throw following the throwing phases.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G7.CREATI.MELODY.MELODY_QUALITIES', 'CREA.G7.CREATI.MELODY', 'creative_arts', 7, 'Name the qualities of a good melody in C major', ARRAY['CREA.G7.CREATI.MELODY.a']::text[], 'The child says a good melody has a clear shape, uses steps and some leaps, repeats a phrase, and ends on the home note C in C major. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G7.RUBRIC.2.1, CREA.G7.RUBRIC.2.2, CREA.G7.RUBRIC.2.3), never as a phone question: b) compose a four-bar melody in C major; c) perform created pieces of music in C major.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G7.CREATI.HANDBALL.HANDBALL', 'CREA.G7.CREATI.HANDBALL', 'creative_arts', 7, 'Describe passing, dribbling and the jump shot in handball', ARRAY['CREA.G7.CREATI.HANDBALL.a']::text[], 'The child says handball is played with the hands, a team has seven players with one goalkeeper, a player may take three steps and hold the ball for three seconds, dribbles by bouncing, and in a jump shot throws while in the air. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G7.RUBRIC.2.1, CREA.G7.RUBRIC.2.2, CREA.G7.RUBRIC.2.3), never as a phone question: b) perform the passing skills in Handball; c) execute dribbling in Handball for skill acquisition; d) execute jump shot in Handball for enjoyment.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G7.CREATI.DESCANT_RECORDER.RECORDER_FACTORS', 'CREA.G7.CREATI.DESCANT_RECORDER', 'creative_arts', 7, 'Name the factors for reading a melody on the recorder', ARRAY['CREA.G7.CREATI.DESCANT_RECORDER.a']::text[], 'The child names the clef, key signature, time signature, note values, rests, dynamics and tempo as things to check before playing. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G7.RUBRIC.2.1, CREA.G7.RUBRIC.2.2, CREA.G7.RUBRIC.2.3), never as a phone question: b) sight read simple melodies on descant recorder from staff notation; c) play a piece in C major on a descant recorder; d) perform simple melodies on a descant recorder observing performance directions.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G7.CREATI.STORYTELLING_AND_ANIMATI.STORY_TECHNIQUES', 'CREA.G7.CREATI.STORYTELLING_AND_ANIMATI', 'creative_arts', 7, 'Name the techniques of storytelling and the qualities of a good flipbook', ARRAY['CREA.G7.CREATI.STORYTELLING_AND_ANIMATI.a', 'CREA.G7.CREATI.STORYTELLING_AND_ANIMATI.b']::text[], 'The child names voice variation, gestures, facial expression, pauses and audience participation, and says a good flipbook has many drawings that change a little each time, in the same place on each page. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G7.RUBRIC.2.1, CREA.G7.RUBRIC.2.2, CREA.G7.RUBRIC.2.3), never as a phone question: c) compose a 3 to 5- minute story addressing an issue in society; d) create a flipbook animation for storytelling; e) perform a 3 to 5- minute story before an audience.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G7.CREATI.FOOTBALL.FOOTBALL_SKILLS', 'CREA.G7.CREATI.FOOTBALL', 'creative_arts', 7, 'Name football skills and how crayon etching is made', ARRAY['CREA.G7.CREATI.FOOTBALL.a', 'CREA.G7.CREATI.FOOTBALL.b', 'CREA.G7.CREATI.FOOTBALL.c', 'CREA.G7.CREATI.FOOTBALL.d']::text[], 'The child says trapping stops and controls the ball, dribbling keeps the ball close while moving, shooting sends it at the goal, a team has eleven players, and crayon etching scratches a top dark layer to show colours beneath. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G7.RUBRIC.2.1, CREA.G7.RUBRIC.2.2, CREA.G7.RUBRIC.2.3), never as a phone question: a) execute trapping skill in football; b) perform dribbling skill in football; c) execute shooting skill in football; e) create a pictorial composition using crayon etching inspired by football game.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G7.CREATI.KENYAN_FOLK_SONGS.FOLK_SONGS', 'CREA.G7.CREATI.KENYAN_FOLK_SONGS', 'creative_arts', 7, 'Classify folk songs in Kenyan communities', ARRAY['CREA.G7.CREATI.KENYAN_FOLK_SONGS.a']::text[], 'The child names kinds of folk songs (lullabies, work songs, wedding songs, initiation songs, war songs, funeral songs, children''s play songs) and what each is sung for. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G7.RUBRIC.2.1, CREA.G7.RUBRIC.2.2, CREA.G7.RUBRIC.2.3), never as a phone question: b) perform a folksong from a Kenyan community with appropriate techniques.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G7.CREATI.INDIGENOUS_KENYAN_CRAFT.BEADWORK', 'CREA.G7.CREATI.INDIGENOUS_KENYAN_CRAFT', 'creative_arts', 7, 'Say what jewellery is for and name materials for beadwork', ARRAY['CREA.G7.CREATI.INDIGENOUS_KENYAN_CRAFT.a', 'CREA.G7.CREATI.INDIGENOUS_KENYAN_CRAFT.b']::text[], 'The child says jewellery decorates, shows identity and status, and marks ceremonies, and names materials for beadwork (beads, thread, wire, needle, leather). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G7.RUBRIC.2.1, CREA.G7.RUBRIC.2.2, CREA.G7.RUBRIC.2.3), never as a phone question: c) make beaded jewellery inspired by patriotism for Kenya; d) sing a patriotic song adorned in beaded jewellery inspired by patriotism.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G7.CREATI.SWIMMING.SWIMMING', 'CREA.G7.CREATI.SWIMMING', 'creative_arts', 7, 'Describe water entry and the backstroke', ARRAY['CREA.G7.CREATI.SWIMMING.a', 'CREA.G7.CREATI.SWIMMING.d']::text[], 'The child says water entry may be feet first or by a dive, that in a pencil dive the body is straight with feet first, that in a crouch dive the body is crouched on the pool edge, and that in backstroke the swimmer lies on the back with alternate arm strokes and a flutter kick; swimming is only with a lifeguard. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G7.RUBRIC.2.1, CREA.G7.RUBRIC.2.2, CREA.G7.RUBRIC.2.3), never as a phone question: b) perform a crouch dive into the swimming pool; c) execute a water entry skill using a pencil dive; d) perform backstroke skill in swimming for skill development.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G7.CREATI.KENYAN_INDIGENOUS_GAMES.ROPE_GAMES', 'CREA.G7.CREATI.KENYAN_INDIGENOUS_GAMES', 'creative_arts', 7, 'Name indigenous rope games and their benefits', ARRAY['CREA.G7.CREATI.KENYAN_INDIGENOUS_GAMES.a', 'CREA.G7.CREATI.KENYAN_INDIGENOUS_GAMES.d']::text[], 'The child names rope skipping, tug of war and rope jumping, and says rope games build fitness, coordination and teamwork. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G7.RUBRIC.2.1, CREA.G7.RUBRIC.2.2, CREA.G7.RUBRIC.2.3), never as a phone question: b) perform different indigenous rope games for skill acquisition; c) perform indigenous rope skipping to a musical rhythm for enjoyment.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G7.APPREC.ANALYSIS_OF_CREATIVE_ART.SPORTS_VALUES', 'CREA.G7.APPREC.ANALYSIS_OF_CREATIVE_ART', 'creative_arts', 7, 'Name the values of clean sports', ARRAY['CREA.G7.APPREC.ANALYSIS_OF_CREATIVE_ART.a']::text[], 'The child names fair play, honesty, respect, teamwork and discipline as the spirit of clean sport, and says cheating and drugs spoil sport. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G7.APPREC.ANALYSIS_OF_CREATIVE_ART.ANALYSIS', 'CREA.G7.APPREC.ANALYSIS_OF_CREATIVE_ART', 'creative_arts', 7, 'Analyse a folk song and a storytelling performance using the right terms', ARRAY['CREA.G7.APPREC.ANALYSIS_OF_CREATIVE_ART.b', 'CREA.G7.APPREC.ANALYSIS_OF_CREATIVE_ART.c']::text[], 'The child analyses a Kenyan folk song by its community, occasion, type, message, soloist and chorus, instruments and costume, and a storytelling performance by its theme, characters, techniques (voice, gesture, pause, audience participation) and lesson, and backs each point with something heard or seen. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G7.RUBRIC.3.1), never as a phone question: d) make portfolio for showcase.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
