INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G7.FOUNDA.INTRODUCTION_TO_CREATIVE.CA_CATEGORIES', 'CREA.G6.CREATI.PAINTING_AND_COLLAGE.TECHNIQUES', 'skill', 'helpful', 'Painting and collage (Grade 6) are examples of the visual arts category. Proposed, to confirm by a CBC Creative Arts and Sports teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
