INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G7.FOUNDA.COMPONENTS_OF_CREATIVE_A.TREBLE_PITCHES', 'CREA.G6.CREATI.MELODY.SOLFA', 'skill', 'essential', 'The sol-fa ladder (Grade 6) is the same scale written on the staff. Proposed, to confirm by a CBC Creative Arts and Sports teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G7.CREATI.DRAWING_AND_PAINTING.BALANCE', 'MATH.G4.GEOMET.PLANE_FIGURES.LINES_SYMMETRY', 'skill', 'essential', 'Lines of symmetry (Grade 4 Maths) explain symmetrical balance. Proposed, to confirm by a CBC Creative Arts and Sports teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G7.CREATI.DRAWING_AND_PAINTING.BALANCE', 'CREA.G6.CREATI.PAINTING_AND_COLLAGE.TECHNIQUES', 'skill', 'helpful', 'Arranging a still life (Grade 6) is arranging for balance. Proposed, to confirm by a CBC Creative Arts and Sports teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G7.CREATI.DRAWING_AND_PAINTING.COLOUR_TEMP', 'CREA.G6.CREATI.PAINTING_AND_COLLAGE.COLOUR_WHEEL', 'skill', 'essential', 'Warm and cool colours were first sorted on the Grade 6 colour wheel. Proposed, to confirm by a CBC Creative Arts and Sports teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G7.CREATI.DRAWING_AND_PAINTING.COLOUR_TEMP', 'CREA.G5.CREATI.PAINTING_AND_MOSAIC.WASH', 'skill', 'helpful', 'A wash for the sky (Grade 5) is where cool colours are used. Proposed, to confirm by a CBC Creative Arts and Sports teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G7.CREATI.RHYTHM.RHYTHM_FACTORS', 'CREA.G7.FOUNDA.COMPONENTS_OF_CREATIVE_A.NOTE_VALUES', 'skill', 'essential', 'Proposed: this skill builds on it. To confirm by a Creative Arts and Sports teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G7.CREATI.RHYTHM.RHYTHM_FACTORS', 'CREA.G6.CREATI.RHYTHM_AND_PATTERN_MAKIN.NOTES', 'skill', 'essential', 'Composing with notes and rests (Grade 6) comes before naming the factors. Proposed, to confirm by a CBC Creative Arts and Sports teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G7.CREATI.JAVELIN_AND_SCULPTURE.JAVELIN', 'CREA.G5.CREATI.ROUNDERS.CARVING', 'skill', 'essential', 'Carving a bat safely (Grade 5) is the same carving skill for a javelin. Proposed, to confirm by a CBC Creative Arts and Sports teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G7.CREATI.JAVELIN_AND_SCULPTURE.JAVELIN', 'CREA.G4.PERFOR.ATHLETICS.SPRINT', 'skill', 'helpful', 'The approach run of a javelin throw is a controlled sprint (Grade 4). Proposed, to confirm by a CBC Creative Arts and Sports teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
