INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G7.CREATI.MELODY.MELODY_QUALITIES', 'CREA.G6.CREATI.MELODY.SOLFA', 'skill', 'essential', 'Melodies within doh to doh'' (Grade 6) are now written in C major. Proposed, to confirm by a CBC Creative Arts and Sports teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
