INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G7.CREATI.HANDBALL.HANDBALL', 'CREA.G4.CREATI.NETBALL.PASSES', 'skill', 'essential', 'Chest and overhead passes (Grade 4 netball) are the handball passes. Proposed, to confirm by a CBC Creative Arts and Sports teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
