INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G7.CREATI.DESCANT_RECORDER.RECORDER_FACTORS', 'CREA.G6.PERFOR.DESCANT_RECORDER.TECHNIQUE', 'skill', 'essential', 'Playing C to D'' with good technique (Grade 6) comes before reading from the staff. Proposed, to confirm by a CBC Creative Arts and Sports teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
