INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G7.CREATI.INDIGENOUS_KENYAN_CRAFT.BEADWORK', 'SOCI.G6.PEOPLE.CULTURE_AND_SOCIAL_ORGAN.CS_AGE', 'skill', 'essential', 'Age-sets in traditional societies (Grade 6 Social Studies) are shown by jewellery. Proposed, to confirm by a CBC Creative Arts and Sports teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
