INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G7.APPREC.ANALYSIS_OF_CREATIVE_ART.SPORTS_VALUES', 'CREA.G5.PERFOR.KENYAN_FOLK_DANCE.DANCE_SAFETY', 'skill', 'helpful', 'Respect for others in performance (Grade 5) is part of the spirit of sport. Proposed, to confirm by a CBC Creative Arts and Sports teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G7.APPREC.ANALYSIS_OF_CREATIVE_ART.SPORTS_VALUES', 'CREA.G5.CREATI.ROUNDERS.SAFETY', 'skill', 'essential', 'Playing safely and by the rules (Grade 5) is fair play. Proposed, to confirm by a CBC Creative Arts and Sports teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G7.APPREC.ANALYSIS_OF_CREATIVE_ART.ANALYSIS', 'CREA.G7.CREATI.KENYAN_FOLK_SONGS.FOLK_SONGS', 'skill', 'essential', 'Proposed: this skill builds on it. To confirm by a Creative Arts and Sports teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G7.APPREC.ANALYSIS_OF_CREATIVE_ART.ANALYSIS', 'CREA.G7.CREATI.STORYTELLING_AND_ANIMATI.STORY_TECHNIQUES', 'skill', 'essential', 'Proposed: this skill builds on it. To confirm by a Creative Arts and Sports teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G7.APPREC.ANALYSIS_OF_CREATIVE_ART.ANALYSIS', 'CREA.G6.APPREC.ANALYSIS_OF_CREATIVE_ART.ELEMENTS', 'skill', 'essential', 'Naming the elements and message of a song (Grade 6) is the first analysis. Proposed, to confirm by a CBC Creative Arts and Sports teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.FOUNDA.INTRODUCTION_TO_CREATIVE.CA_CATEGORIES.M_CA7_CC_ONE_ONLY', 'CREA.G7.FOUNDA.INTRODUCTION_TO_CREATIVE.CA_CATEGORIES', 'Thinks the categories never work together, so music has nothing to do with dance or drama.', '{"question":"How do music and dance relate?","wrong_answer":"They never go together","correct_answer":"They often work together"}'::jsonb, 'Each category is taught in its own lesson, so the child sees them as separate subjects.', 'Offer "They never go together" next to the right answer and ask the question again in a new situation.', 'Watch a folk dance: name the music, the movement and the costume, three categories in one.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.FOUNDA.INTRODUCTION_TO_CREATIVE.CA_CATEGORIES.M_CA7_CC_SPORT', 'CREA.G7.FOUNDA.INTRODUCTION_TO_CREATIVE.CA_CATEGORIES', 'Leaves physical education and sports out of the subject and names an unrelated subject instead.', '{"question":"Which is a category of Creative Arts and Sports?","wrong_answer":"Mathematics","correct_answer":"Physical education and sports"}'::jsonb, 'Until Grade 6 PE was a separate lesson, so the child does not expect it in Creative Arts.', 'Offer "Mathematics" next to the right answer and ask the question again in a new situation.', 'Read the subject name aloud: Creative Arts and Sports. List what PE adds.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.FOUNDA.INTRODUCTION_TO_CREATIVE.CA_CATEGORIES.M_CA7_CC_ARTS', 'CREA.G7.FOUNDA.INTRODUCTION_TO_CREATIVE.CA_CATEGORIES', 'Thinks only painting is art and craft, putting football there because it is creative.', '{"question":"Which is art and craft?","wrong_answer":"Playing football","correct_answer":"Making a collage"}'::jsonb, 'The child uses "creative" to mean any fun activity.', 'Offer "Playing football" next to the right answer and ask the question again in a new situation.', 'Sort ten activities into visual arts, performing arts and sports with the reason for each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.FOUNDA.INTRODUCTION_TO_CREATIVE.CA_CATEGORIES.M_CA7_CC_DRAMA_SPORT', 'CREA.G7.FOUNDA.INTRODUCTION_TO_CREATIVE.CA_CATEGORIES', 'Puts drama under sports because both are performed in front of people.', '{"question":"Which category does drama belong to?","wrong_answer":"sports","correct_answer":"performing arts"}'::jsonb, 'Both drama and sport have an audience and a stage or field.', 'Offer "sports" next to the right answer and ask the question again in a new context.', 'Ask what the performer does: tells a story (performing arts) or competes (sport).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.FOUNDA.COMPONENTS_OF_CREATIVE_A.STORY_ELEMENTS.M_CA7_SE_SETTING', 'CREA.G7.FOUNDA.COMPONENTS_OF_CREATIVE_A.STORY_ELEMENTS', 'Says setting is the people.', '{"question":"What is the setting of a story?","wrong_answer":"The people in it","correct_answer":"Where and when it happens"}'::jsonb, 'Characters are the first thing the child notices in a story, so "setting" gets their meaning.', 'Offer "The people in it" next to the right answer and ask the question again in a new situation.', 'Ask "where and when?" for three stories and underline the answers.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.FOUNDA.COMPONENTS_OF_CREATIVE_A.STORY_ELEMENTS.M_CA7_SE_CHARACTER', 'CREA.G7.FOUNDA.COMPONENTS_OF_CREATIVE_A.STORY_ELEMENTS', 'Says characters are the place.', '{"question":"Who are the characters?","wrong_answer":"The place of the story","correct_answer":"The people or animals in it"}'::jsonb, 'The child swaps two new words learnt in the same lesson.', 'Offer "The place of the story" next to the right answer and ask the question again in a new situation.', 'Ask "who?" for characters and "where?" for setting with one story.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.FOUNDA.COMPONENTS_OF_CREATIVE_A.STORY_ELEMENTS.M_CA7_SE_PLOT', 'CREA.G7.FOUNDA.COMPONENTS_OF_CREATIVE_A.STORY_ELEMENTS', 'Says plot is the title.', '{"question":"What is the plot?","wrong_answer":"The title of the story","correct_answer":"The order of events"}'::jsonb, 'The title is at the top and seems to sum up the story, so the child calls it the plot.', 'Offer "The title of the story" next to the right answer and ask the question again in a new situation.', 'Retell a story in three events: that chain is the plot.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.FOUNDA.COMPONENTS_OF_CREATIVE_A.FITNESS_COMPONENTS.M_CA7_FC_AGILITY', 'CREA.G7.FOUNDA.COMPONENTS_OF_CREATIVE_A.FITNESS_COMPONENTS', 'Mixes agility with flexibility.', '{"question":"Which is the ability to change direction quickly?","wrong_answer":"Flexibility","correct_answer":"Agility"}'::jsonb, 'Both agility and flexibility sound like being good at moving.', 'Offer "Flexibility" next to the right answer and ask the question again in a new situation.', 'Do a zigzag run (agility) and a sit-and-reach (flexibility); name each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.FOUNDA.COMPONENTS_OF_CREATIVE_A.FITNESS_COMPONENTS.M_CA7_FC_FLEX', 'CREA.G7.FOUNDA.COMPONENTS_OF_CREATIVE_A.FITNESS_COMPONENTS', 'Mixes flexibility with strength.', '{"question":"Which is the range of movement at a joint?","wrong_answer":"Strength","correct_answer":"Flexibility"}'::jsonb, 'A flexible person can lift a leg high, which the child sees as strength.', 'Offer "Strength" next to the right answer and ask the question again in a new situation.', 'Compare touching the toes (flexibility) with lifting a heavy bag (strength).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.FOUNDA.COMPONENTS_OF_CREATIVE_A.FITNESS_COMPONENTS.M_CA7_FC_ENDURANCE', 'CREA.G7.FOUNDA.COMPONENTS_OF_CREATIVE_A.FITNESS_COMPONENTS', 'Mixes endurance with speed.', '{"question":"Which is lasting a long time without tiring?","wrong_answer":"Speed","correct_answer":"Endurance"}'::jsonb, 'Fast runners win races, so the child thinks speed is what lasts.', 'Offer "Speed" next to the right answer and ask the question again in a new situation.', 'Compare a 60 m sprint (speed) with a 1,500 m run (endurance).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.FOUNDA.COMPONENTS_OF_CREATIVE_A.NOTE_VALUES.M_CA7_NV_MINIM', 'CREA.G7.FOUNDA.COMPONENTS_OF_CREATIVE_A.NOTE_VALUES', 'Gives a minim one beat, taking it for a crotchet.', '{"question":"How many beats is a minim?","wrong_answer":"1","correct_answer":"2"}'::jsonb, 'The minim and the crotchet both have a stem; only the hollow head differs.', 'Offer "1" next to the right answer and ask the question again in a new situation.', 'Draw both: hollow head and stem is the minim, two beats; filled head is the crotchet, one.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.FOUNDA.COMPONENTS_OF_CREATIVE_A.NOTE_VALUES.M_CA7_NV_SEMIBREVE', 'CREA.G7.FOUNDA.COMPONENTS_OF_CREATIVE_A.NOTE_VALUES', 'Gives a semibreve two beats, taking it for a minim.', '{"question":"How many beats is a semibreve?","wrong_answer":"2","correct_answer":"4"}'::jsonb, 'Both have hollow heads; the child does not notice the semibreve has no stem.', 'Offer "2" next to the right answer and ask the question again in a new situation.', 'Line up semibreve, minim, crotchet and count 4, 2, 1 while clapping.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.FOUNDA.COMPONENTS_OF_CREATIVE_A.NOTE_VALUES.M_CA7_NV_BAR', 'CREA.G7.FOUNDA.COMPONENTS_OF_CREATIVE_A.NOTE_VALUES', 'Puts four crotchet beats in a bar of two-four time, reading the lower 4 as the count.', '{"question":"In 2 time, a bar holds how many crotchet beats?","wrong_answer":"4","correct_answer":"2"}'::jsonb, 'The child reads the bottom number of 2/4 as the number of beats.', 'Offer "4" next to the right answer and ask the question again in a new situation.', 'The top number counts the beats: 2/4 has two crotchet beats in a bar.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.FOUNDA.COMPONENTS_OF_CREATIVE_A.TREBLE_PITCHES.M_CA7_TP_LINES', 'CREA.G7.FOUNDA.COMPONENTS_OF_CREATIVE_A.TREBLE_PITCHES', 'Gives the spaces for the lines.', '{"question":"What are the lines of the treble staff from the bottom?","wrong_answer":"F A C E","correct_answer":"E G B D F"}'::jsonb, 'FACE is the easiest rhyme to remember, so the child uses it for everything.', 'Offer "F A C E" next to the right answer and ask the question again in a new situation.', 'Lines: Every Good Boy Deserves Fruit. Spaces: FACE.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.FOUNDA.COMPONENTS_OF_CREATIVE_A.TREBLE_PITCHES.M_CA7_TP_SPACES', 'CREA.G7.FOUNDA.COMPONENTS_OF_CREATIVE_A.TREBLE_PITCHES', 'Gives the lines for the spaces.', '{"question":"What are the spaces of the treble staff from the bottom?","wrong_answer":"E G B D F","correct_answer":"F A C E"}'::jsonb, 'The child learnt both rhymes and swaps them.', 'Offer "E G B D F" next to the right answer and ask the question again in a new situation.', 'Point at a space: FACE fits in the spaces.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.FOUNDA.COMPONENTS_OF_CREATIVE_A.TREBLE_PITCHES.M_CA7_TP_FIRST', 'CREA.G7.FOUNDA.COMPONENTS_OF_CREATIVE_A.TREBLE_PITCHES', 'Names the bottom line of the treble staff F, starting FACE on a line.', '{"question":"Which note is on the bottom line of the treble staff?","wrong_answer":"F","correct_answer":"E"}'::jsonb, 'The child starts FACE at the bottom of the staff, not in the first space.', 'Offer "F" next to the right answer and ask the question again in a new situation.', 'Count up from the bottom line: E (line), F (space), G (line).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.FOUNDA.COMPONENTS_OF_CREATIVE_A.STORY_ELEMENTS.M_CA7_SE_THEME_TITLE', 'CREA.G7.FOUNDA.COMPONENTS_OF_CREATIVE_A.STORY_ELEMENTS', 'Says the theme of a story is its title.', '{"question":"What is the theme of a story?","wrong_answer":"its title","correct_answer":"the main idea or lesson it is about"}'::jsonb, 'The title is the first words and seems to say what the story is about.', 'Offer "its title" next to the right answer and ask the question again in a new context.', 'Read a fable: the title names the animals, the theme is the lesson.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.FOUNDA.COMPONENTS_OF_CREATIVE_A.FITNESS_COMPONENTS.M_CA7_FC_STRENGTH_SIZE', 'CREA.G7.FOUNDA.COMPONENTS_OF_CREATIVE_A.FITNESS_COMPONENTS', 'Thinks muscular strength is the same as being big.', '{"question":"What is muscular strength?","wrong_answer":"being big","correct_answer":"the force a muscle can produce"}'::jsonb, 'Strong people in films are often big.', 'Offer "being big" next to the right answer and ask the question again in a new context.', 'Compare a small learner lifting a heavy load with a big learner who cannot.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.FOUNDA.COMPONENTS_OF_CREATIVE_A.NOTE_VALUES.M_CA7_NV_QUAVER_BEAT', 'CREA.G7.FOUNDA.COMPONENTS_OF_CREATIVE_A.NOTE_VALUES', 'Gives a single quaver one whole beat.', '{"question":"How long is one quaver in two-four time?","wrong_answer":"one beat","correct_answer":"half a beat"}'::jsonb, 'Each quaver has its own stem and flag, so the child counts it as a whole note.', 'Offer "one beat" next to the right answer and ask the question again in a new context.', 'Clap ta-te: two quavers share one beat.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.FOUNDA.COMPONENTS_OF_CREATIVE_A.TREBLE_PITCHES.M_CA7_TP_LEDGER_C', 'CREA.G7.FOUNDA.COMPONENTS_OF_CREATIVE_A.TREBLE_PITCHES', 'Names the note on the ledger line below the treble staff D.', '{"question":"Which note sits on one ledger line below the treble staff?","wrong_answer":"D","correct_answer":"middle C"}'::jsonb, 'The child counts down from E but forgets the space below is D and the ledger line is C.', 'Offer "D" next to the right answer and ask the question again in a new context.', 'Count down: E line, D space, C ledger line.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.CREATI.DRAWING_AND_PAINTING.BALANCE.M_CA7_BL_SYM', 'CREA.G7.CREATI.DRAWING_AND_PAINTING.BALANCE', 'Says symmetrical balance has two different sides, swapping it with asymmetrical.', '{"question":"What is symmetrical balance?","wrong_answer":"Both sides are different","correct_answer":"Both sides are alike"}'::jsonb, 'Symmetrical and asymmetrical sound alike.', 'Offer "Both sides are different" next to the right answer and ask the question again in a new situation.', 'Fold a butterfly drawing: both halves match, so symmetrical.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.CREATI.DRAWING_AND_PAINTING.BALANCE.M_CA7_BL_MEANING', 'CREA.G7.CREATI.DRAWING_AND_PAINTING.BALANCE', 'Thinks balance means making every part the same colour.', '{"question":"What is balance in a picture?","wrong_answer":"Making everything the same colour","correct_answer":"Spreading visual weight evenly"}'::jsonb, 'The child links balance with sameness.', 'Offer "Making everything the same colour" next to the right answer and ask the question again in a new situation.', 'Show a big shape balanced by two small ones of the same visual weight.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.CREATI.DRAWING_AND_PAINTING.BALANCE.M_CA7_BL_RADIAL', 'CREA.G7.CREATI.DRAWING_AND_PAINTING.BALANCE', 'Picks "items in a straight line" for radial balance.', '{"question":"What is radial balance?","wrong_answer":"Items in a straight line","correct_answer":"Items spread from the centre"}'::jsonb, 'The child has not met "radius", so radial means nothing.', 'Offer "Items in a straight line" next to the right answer and ask the question again in a new situation.', 'Show a sunflower or a wheel: parts spread out from the centre.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.CREATI.DRAWING_AND_PAINTING.COLOUR_TEMP.M_CA7_CT_WARM', 'CREA.G7.CREATI.DRAWING_AND_PAINTING.COLOUR_TEMP', 'Puts blue among warm colours.', '{"question":"Which is a warm colour?","wrong_answer":"Blue","correct_answer":"Orange"}'::jsonb, 'The child thinks of colours they like as warm.', 'Offer "Blue" next to the right answer and ask the question again in a new situation.', 'Sort colours by fire (warm) and water (cool).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.CREATI.DRAWING_AND_PAINTING.COLOUR_TEMP.M_CA7_CT_COOL', 'CREA.G7.CREATI.DRAWING_AND_PAINTING.COLOUR_TEMP', 'Puts red among cool colours.', '{"question":"Which is a cool colour?","wrong_answer":"Red","correct_answer":"Blue"}'::jsonb, 'Red is a strong colour, and the child mixes strong with cool.', 'Offer "Red" next to the right answer and ask the question again in a new situation.', 'Hold red near a picture of fire and blue near water.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.CREATI.DRAWING_AND_PAINTING.COLOUR_TEMP.M_CA7_CT_FEEL', 'CREA.G7.CREATI.DRAWING_AND_PAINTING.COLOUR_TEMP', 'Mixes the feeling of warm and cool.', '{"question":"Which colours remind us of the sun and fire?","wrong_answer":"Cool colours","correct_answer":"Warm colours"}'::jsonb, 'The child has heard "cool" used to mean good.', 'Offer "Cool colours" next to the right answer and ask the question again in a new situation.', 'Ask what the sun looks like: red, orange, yellow are warm.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.CREATI.DRAWING_AND_PAINTING.BALANCE.M_CA7_BL_CENTRE_ONLY', 'CREA.G7.CREATI.DRAWING_AND_PAINTING.BALANCE', 'Thinks a picture is only balanced if the main object is in the exact centre.', '{"question":"Can a picture be balanced with the main tree on the left?","wrong_answer":"no, it must be in the centre","correct_answer":"yes, if something on the right balances its weight"}'::jsonb, 'The child knows only symmetrical balance.', 'Offer "no, it must be in the centre" next to the right answer and ask the question again in a new context.', 'Balance a big tree on the left with a house and a bird on the right.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.CREATI.DRAWING_AND_PAINTING.COLOUR_TEMP.M_CA7_CT_DISTANCE', 'CREA.G7.CREATI.DRAWING_AND_PAINTING.COLOUR_TEMP', 'Paints far hills in warm red, so they jump forward.', '{"question":"Which colours make hills look far away?","wrong_answer":"warm colours","correct_answer":"cool colours, such as blue"}'::jsonb, 'The child picks bright colours to make things noticed.', 'Offer "warm colours" next to the right answer and ask the question again in a new context.', 'Paint two strips of hills, warm and cool; which looks further?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.CREATI.RHYTHM.RHYTHM_FACTORS.M_CA7_RF_BEATS', 'CREA.G7.CREATI.RHYTHM.RHYTHM_FACTORS', 'Thinks the notes in a bar of two-four time may add up to any number of beats.', '{"question":"In a bar of 2 time, the notes must add up to...","wrong_answer":"Any number of beats","correct_answer":"Two crotchet beats"}'::jsonb, 'The child writes rhythms by ear and does not check the count.', 'Offer "Any number of beats" next to the right answer and ask the question again in a new situation.', 'Count each bar aloud and tick it when it makes two.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.CREATI.RHYTHM.RHYTHM_FACTORS.M_CA7_RF_FACTOR', 'CREA.G7.CREATI.RHYTHM.RHYTHM_FACTORS', 'Names the colour of the paper as a factor in making a rhythm.', '{"question":"Which is a factor in making a rhythm?","wrong_answer":"The colour of the paper","correct_answer":"The time signature"}'::jsonb, 'The child lists anything on the page rather than what decides the sound.', 'Offer "The colour of the paper" next to the right answer and ask the question again in a new situation.', 'Ask: does it change what we hear? Only those are factors.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.CREATI.RHYTHM.RHYTHM_FACTORS.M_CA7_RF_BARS', 'CREA.G7.CREATI.RHYTHM.RHYTHM_FACTORS', 'Says a four-bar pattern has two bars, counting the bar lines in the middle.', '{"question":"How many bars are in a four-bar pattern?","wrong_answer":"Two","correct_answer":"Four"}'::jsonb, 'The child counts bar lines instead of the spaces between them.', 'Offer "Two" next to the right answer and ask the question again in a new situation.', 'Number each bar above the staff: 1, 2, 3, 4.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.CREATI.RHYTHM.RHYTHM_FACTORS.M_CA7_RF_NO_END', 'CREA.G7.CREATI.RHYTHM.RHYTHM_FACTORS', 'Ends a rhythmic pattern on a quaver, so it feels unfinished.', '{"question":"Which ending makes a four-bar rhythm sound finished?","wrong_answer":"a single quaver","correct_answer":"a long note such as a minim"}'::jsonb, 'The child stops when the bars are full, not when the rhythm rests.', 'Offer "a single quaver" next to the right answer and ask the question again in a new context.', 'Clap both endings; ask which feels finished.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.CREATI.JAVELIN_AND_SCULPTURE.JAVELIN.M_CA7_JV_MATERIAL', 'CREA.G7.CREATI.JAVELIN_AND_SCULPTURE.JAVELIN', 'Names iron as a material to carve a javelin, choosing the strongest material.', '{"question":"Which material suits carving a javelin?","wrong_answer":"Iron","correct_answer":"Soft wood"}'::jsonb, 'The child knows real javelins are metal-tipped and thinks of carving metal.', 'Offer "Iron" next to the right answer and ask the question again in a new situation.', 'Ask what a knife can shape: soft wood and bamboo, not iron.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.CREATI.JAVELIN_AND_SCULPTURE.JAVELIN.M_CA7_JV_PHASE', 'CREA.G7.CREATI.JAVELIN_AND_SCULPTURE.JAVELIN', 'Puts the delivery first, before the grip and approach.', '{"question":"Which phase comes first in a javelin throw?","wrong_answer":"Delivery","correct_answer":"Grip and carry"}'::jsonb, 'The throw is the part everyone watches, so the child puts it first.', 'Offer "Delivery" next to the right answer and ask the question again in a new situation.', 'Walk through the phases slowly with a stick: grip, run, cross-step, throw, recover.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.CREATI.JAVELIN_AND_SCULPTURE.JAVELIN.M_CA7_JV_SAFETY', 'CREA.G7.CREATI.JAVELIN_AND_SCULPTURE.JAVELIN', 'Says a javelin may be thrown anywhere, even near people.', '{"question":"Where is a javelin thrown?","wrong_answer":"Anywhere among people","correct_answer":"Only in a cleared field with a teacher"}'::jsonb, 'The child sees a light carved stick as harmless.', 'Offer "Anywhere among people" next to the right answer and ask the question again in a new situation.', 'Show the point and the distance it flies; mark the safe zone.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.CREATI.JAVELIN_AND_SCULPTURE.JAVELIN.M_CA7_JV_FETCH_ANY', 'CREA.G7.CREATI.JAVELIN_AND_SCULPTURE.JAVELIN', 'Runs to fetch a javelin while others are still throwing.', '{"question":"When may you collect your javelin?","wrong_answer":"straight after your throw","correct_answer":"only when the teacher says all throws are done"}'::jsonb, 'The child wants to see how far it went.', 'Offer "straight after your throw" next to the right answer and ask the question again in a new context.', 'Practise the signal: throw, wait, collect together.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.CREATI.MELODY.MELODY_QUALITIES.M_CA7_MQ_HOME', 'CREA.G7.CREATI.MELODY.MELODY_QUALITIES', 'Ends a C major melody on G, the note that sounds like a pause.', '{"question":"On which note does a melody in C major end?","wrong_answer":"G","correct_answer":"C"}'::jsonb, 'G often ends the first phrase, so the child thinks it ends the melody.', 'Offer "G" next to the right answer and ask the question again in a new situation.', 'Sing ending on G and on C; C sounds finished.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.CREATI.MELODY.MELODY_QUALITIES.M_CA7_MQ_SHAPE', 'CREA.G7.CREATI.MELODY.MELODY_QUALITIES', 'Thinks a good melody has no pattern, so any notes in any order will do.', '{"question":"Which is a quality of a good melody?","wrong_answer":"No pattern at all","correct_answer":"A clear shape with steps and leaps"}'::jsonb, 'The child thinks creativity means no rules.', 'Offer "No pattern at all" next to the right answer and ask the question again in a new situation.', 'Draw the melody''s shape as a line: up, then down to C.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.CREATI.MELODY.MELODY_QUALITIES.M_CA7_MQ_REPEAT', 'CREA.G7.CREATI.MELODY.MELODY_QUALITIES', 'Thinks repetition is wrong.', '{"question":"Why repeat a phrase in a melody?","wrong_answer":"To make it harder to sing","correct_answer":"To make it easy to remember"}'::jsonb, 'At school, copying is wrong, so the child thinks repeating a phrase is weak.', 'Offer "To make it harder to sing" next to the right answer and ask the question again in a new situation.', 'Sing a well-known song and count its repeated phrases.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.CREATI.MELODY.MELODY_QUALITIES.M_CA7_MQ_SHARPS', 'CREA.G7.CREATI.MELODY.MELODY_QUALITIES', 'Adds sharps or flats to a melody in C major.', '{"question":"Does a melody in C major need sharps or flats?","wrong_answer":"yes, F sharp","correct_answer":"no; C major has none"}'::jsonb, 'The child has seen sharps in G major pieces.', 'Offer "yes, F sharp" next to the right answer and ask the question again in a new context.', 'Play the C scale on white keys or recorder: no sharps.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.CREATI.HANDBALL.HANDBALL.M_CA7_HB_PLAYERS', 'CREA.G7.CREATI.HANDBALL.HANDBALL', 'Says a handball team has eleven players, taking the football number.', '{"question":"How many players are in a handball team, with the goalkeeper?","wrong_answer":"Eleven","correct_answer":"Seven"}'::jsonb, 'Football is the team game the child knows best.', 'Offer "Eleven" next to the right answer and ask the question again in a new situation.', 'Count the positions on a handball court drawing: six and a goalkeeper.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.CREATI.HANDBALL.HANDBALL.M_CA7_HB_HANDS', 'CREA.G7.CREATI.HANDBALL.HANDBALL', 'Says handball is played with the feet.', '{"question":"How is handball played?","wrong_answer":"With the feet","correct_answer":"With the hands"}'::jsonb, 'The child pictures football, the most common ball game.', 'Offer "With the feet" next to the right answer and ask the question again in a new situation.', 'Say the name slowly: hand-ball.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.CREATI.HANDBALL.HANDBALL.M_CA7_HB_STEPS', 'CREA.G7.CREATI.HANDBALL.HANDBALL', 'Says a player may take ten steps with the ball, as long as they keep moving.', '{"question":"How many steps may a player take with the ball?","wrong_answer":"Ten","correct_answer":"Three"}'::jsonb, 'The child mixes handball with rugby, where players run with the ball.', 'Offer "Ten" next to the right answer and ask the question again in a new situation.', 'Walk three steps with the ball, then pass or bounce.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.CREATI.HANDBALL.HANDBALL.M_CA7_HB_AREA', 'CREA.G7.CREATI.HANDBALL.HANDBALL', 'Thinks field players may stand in the goal area.', '{"question":"May a field player stand inside the goal area?","wrong_answer":"yes","correct_answer":"no; only the goalkeeper"}'::jsonb, 'The child copies football, where players enter the box.', 'Offer "yes" next to the right answer and ask the question again in a new context.', 'Mark the goal area line on the court.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.CREATI.DESCANT_RECORDER.RECORDER_FACTORS.M_CA7_RC_FACTOR', 'CREA.G7.CREATI.DESCANT_RECORDER.RECORDER_FACTORS', 'Names the colour of the recorder as something to check before playing.', '{"question":"What should you check before playing a melody?","wrong_answer":"The colour of the recorder","correct_answer":"The time signature and key"}'::jsonb, 'The child lists what they see, not what the music asks for.', 'Offer "The colour of the recorder" next to the right answer and ask the question again in a new situation.', 'Read a piece from left to right: clef, key, time, then notes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.CREATI.DESCANT_RECORDER.RECORDER_FACTORS.M_CA7_RC_REST', 'CREA.G7.CREATI.DESCANT_RECORDER.RECORDER_FACTORS', 'Thinks a rest means play louder.', '{"question":"What does a rest mean?","wrong_answer":"Play louder","correct_answer":"Be silent for its length"}'::jsonb, 'The rest symbols look like dynamics marks to the child.', 'Offer "Play louder" next to the right answer and ask the question again in a new situation.', 'Clap a line and hold still at each rest.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.CREATI.DESCANT_RECORDER.RECORDER_FACTORS.M_CA7_RC_TEMPO', 'CREA.G7.CREATI.DESCANT_RECORDER.RECORDER_FACTORS', 'Says dynamics tells how fast to play.', '{"question":"Which tells how fast to play?","wrong_answer":"Dynamics","correct_answer":"Tempo"}'::jsonb, 'Both are Italian words above the music.', 'Offer "Dynamics" next to the right answer and ask the question again in a new situation.', 'Sort words: allegro, andante (tempo); forte, piano (dynamics).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.CREATI.DESCANT_RECORDER.RECORDER_FACTORS.M_CA7_RC_KEY_SKIP', 'CREA.G7.CREATI.DESCANT_RECORDER.RECORDER_FACTORS', 'Ignores the key signature and plays every note as written without sharps.', '{"question":"A piece has one sharp at the start, on the F line. What do you play for every F?","wrong_answer":"F","correct_answer":"F sharp"}'::jsonb, 'The child reads notes one by one and forgets the start of the line.', 'Offer "F" next to the right answer and ask the question again in a new context.', 'Circle every F before playing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.CREATI.STORYTELLING_AND_ANIMATI.STORY_TECHNIQUES.M_CA7_ST_VOICE', 'CREA.G7.CREATI.STORYTELLING_AND_ANIMATI.STORY_TECHNIQUES', 'Thinks a storyteller must keep one flat voice to be clear.', '{"question":"Which is a storytelling technique?","wrong_answer":"Using one flat voice","correct_answer":"Varying the voice"}'::jsonb, 'Reading aloud at school is often in one steady voice.', 'Offer "Using one flat voice" next to the right answer and ask the question again in a new situation.', 'Tell one line in a flat voice and then as the hyena; ask which holds attention.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.CREATI.STORYTELLING_AND_ANIMATI.STORY_TECHNIQUES.M_CA7_ST_FLIP', 'CREA.G7.CREATI.STORYTELLING_AND_ANIMATI.STORY_TECHNIQUES', 'Says a flipbook has one picture.', '{"question":"What does a good flipbook have?","wrong_answer":"One picture","correct_answer":"Many pictures that change a little"}'::jsonb, 'The child has not seen a flipbook and pictures a single drawing.', 'Offer "One picture" next to the right answer and ask the question again in a new situation.', 'Flip a ten-page flipbook of a bouncing ball.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.CREATI.STORYTELLING_AND_ANIMATI.STORY_TECHNIQUES.M_CA7_ST_AUDIENCE', 'CREA.G7.CREATI.STORYTELLING_AND_ANIMATI.STORY_TECHNIQUES', 'Thinks the audience must stay silent through a story.', '{"question":"How can a storyteller involve the audience?","wrong_answer":"Never let them speak","correct_answer":"Ask them to join in"}'::jsonb, 'School rules say listen quietly.', 'Offer "Never let them speak" next to the right answer and ask the question again in a new situation.', 'Use a call-and-response opening the class answers.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.CREATI.STORYTELLING_AND_ANIMATI.STORY_TECHNIQUES.M_CA7_ST_BIG_JUMPS', 'CREA.G7.CREATI.STORYTELLING_AND_ANIMATI.STORY_TECHNIQUES', 'Draws flipbook pages with big changes, so the movement jumps.', '{"question":"In a flipbook, should each page change a lot or a little?","wrong_answer":"a lot","correct_answer":"a little, so the movement looks smooth"}'::jsonb, 'The child wants each page to show something new.', 'Offer "a lot" next to the right answer and ask the question again in a new context.', 'Flip two books, big changes and small; compare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.CREATI.FOOTBALL.FOOTBALL_SKILLS.M_CA7_FS_TRAP', 'CREA.G7.CREATI.FOOTBALL.FOOTBALL_SKILLS', 'Says trapping means kicking at the goal, swapping it with shooting.', '{"question":"What is trapping?","wrong_answer":"Kicking at the goal","correct_answer":"Stopping and controlling the ball"}'::jsonb, 'Both happen when the ball arrives at the player''s feet.', 'Offer "Kicking at the goal" next to the right answer and ask the question again in a new situation.', 'Trap a ball dead under the sole, then shoot; name each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.CREATI.FOOTBALL.FOOTBALL_SKILLS.M_CA7_FS_DRIBBLE', 'CREA.G7.CREATI.FOOTBALL.FOOTBALL_SKILLS', 'Says dribbling is passing to a friend.', '{"question":"What is dribbling?","wrong_answer":"Passing to a friend","correct_answer":"Keeping the ball close while moving"}'::jsonb, 'Both move the ball forward along the ground.', 'Offer "Passing to a friend" next to the right answer and ask the question again in a new situation.', 'Dribble round cones alone, then pass; name each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.CREATI.FOOTBALL.FOOTBALL_SKILLS.M_CA7_FS_ETCH', 'CREA.G7.CREATI.FOOTBALL.FOOTBALL_SKILLS', 'Says crayon etching is made by painting over water.', '{"question":"How is crayon etching made?","wrong_answer":"By painting over water","correct_answer":"By scratching a dark top layer"}'::jsonb, 'The child mixes it with wax-resist painting.', 'Offer "By painting over water" next to the right answer and ask the question again in a new situation.', 'Scratch through a dark crayon layer to show colours.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.CREATI.FOOTBALL.FOOTBALL_SKILLS.M_CA7_FS_SHOOT_TOE', 'CREA.G7.CREATI.FOOTBALL.FOOTBALL_SKILLS', 'Shoots with the toe for power.', '{"question":"Which part of the foot gives a powerful, accurate shot?","wrong_answer":"the toe","correct_answer":"the laces (instep)"}'::jsonb, 'The toe is the closest part to the ball.', 'Offer "the toe" next to the right answer and ask the question again in a new context.', 'Shoot five with the toe and five with the laces; count on target.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.CREATI.KENYAN_FOLK_SONGS.FOLK_SONGS.M_CA7_FO_LULLABY', 'CREA.G7.CREATI.KENYAN_FOLK_SONGS.FOLK_SONGS', 'Says a lullaby is a war song.', '{"question":"What is a lullaby for?","wrong_answer":"Going to war","correct_answer":"Putting a baby to sleep"}'::jsonb, 'The child has not heard the word "lullaby" and guesses.', 'Offer "Going to war" next to the right answer and ask the question again in a new situation.', 'Hum a lullaby softly; ask who it is for.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.CREATI.KENYAN_FOLK_SONGS.FOLK_SONGS.M_CA7_FO_WORK', 'CREA.G7.CREATI.KENYAN_FOLK_SONGS.FOLK_SONGS', 'Says a work song is sung at bedtime.', '{"question":"When is a work song sung?","wrong_answer":"At bedtime","correct_answer":"While working"}'::jsonb, 'The child mixes up the occasions of two song types.', 'Offer "At bedtime" next to the right answer and ask the question again in a new situation.', 'Sing a work song while miming digging in time.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.CREATI.KENYAN_FOLK_SONGS.FOLK_SONGS.M_CA7_FO_FUNERAL', 'CREA.G7.CREATI.KENYAN_FOLK_SONGS.FOLK_SONGS', 'Says a wedding song is sung at a funeral.', '{"question":"Which song is sung at a funeral?","wrong_answer":"A wedding song","correct_answer":"A dirge"}'::jsonb, 'Both are sung by big gatherings at family events.', 'Offer "A wedding song" next to the right answer and ask the question again in a new situation.', 'Compare the mood and tempo: slow and sad (dirge), lively (wedding).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.CREATI.KENYAN_FOLK_SONGS.FOLK_SONGS.M_CA7_FO_PRAISE_CHURCH', 'CREA.G7.CREATI.KENYAN_FOLK_SONGS.FOLK_SONGS', 'Calls every praise song a church song.', '{"question":"A song praises a brave hunter. What type is it?","wrong_answer":"a church song","correct_answer":"a praise song (folk)"}'::jsonb, 'The child links "praise" only with worship.', 'Offer "a church song" next to the right answer and ask the question again in a new context.', 'Read the words: who is praised?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.CREATI.INDIGENOUS_KENYAN_CRAFT.BEADWORK.M_CA7_BW_MATERIAL', 'CREA.G7.CREATI.INDIGENOUS_KENYAN_CRAFT.BEADWORK', 'Names cement as a beadwork material.', '{"question":"Which is a material for beadwork?","wrong_answer":"Cement","correct_answer":"Thread and beads"}'::jsonb, 'The child lists building materials as "materials".', 'Offer "Cement" next to the right answer and ask the question again in a new situation.', 'Sort materials you can thread from those you cannot.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.CREATI.INDIGENOUS_KENYAN_CRAFT.BEADWORK.M_CA7_BW_FUNCTION', 'CREA.G7.CREATI.INDIGENOUS_KENYAN_CRAFT.BEADWORK', 'Says jewellery shows nothing in Kenyan communities, only decoration.', '{"question":"What does jewellery show in Kenyan communities?","wrong_answer":"Nothing at all","correct_answer":"Identity, status and ceremonies"}'::jsonb, 'The child sees jewellery only as fashion.', 'Offer "Nothing at all" next to the right answer and ask the question again in a new situation.', 'Look at pictures of Maasai beadwork: colours show age and status.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.CREATI.INDIGENOUS_KENYAN_CRAFT.BEADWORK.M_CA7_BW_TOOL', 'CREA.G7.CREATI.INDIGENOUS_KENYAN_CRAFT.BEADWORK', 'Names a hammer as the tool for beading.', '{"question":"Which tool is used for beading?","wrong_answer":"A hammer","correct_answer":"A needle"}'::jsonb, 'The child thinks of tools from woodwork.', 'Offer "A hammer" next to the right answer and ask the question again in a new situation.', 'Thread beads with a needle and show why a hammer would break them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.CREATI.INDIGENOUS_KENYAN_CRAFT.BEADWORK.M_CA7_BW_COLOUR_RANDOM', 'CREA.G7.CREATI.INDIGENOUS_KENYAN_CRAFT.BEADWORK', 'Thinks bead colours in traditional jewellery are chosen at random.', '{"question":"Do colours in traditional Kenyan beadwork carry meaning?","wrong_answer":"no, any colour","correct_answer":"yes; in many communities colours stand for things such as peace or bravery"}'::jsonb, 'The child sees beads only as decoration.', 'Offer "no, any colour" next to the right answer and ask the question again in a new context.', 'Read what each colour means in one community.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.CREATI.SWIMMING.SWIMMING.M_CA7_SM_PENCIL', 'CREA.G7.CREATI.SWIMMING.SWIMMING', 'Says a pencil dive enters head first with arms apart.', '{"question":"In a pencil dive, how does the body enter the water?","wrong_answer":"Head first with arms apart","correct_answer":"Feet first, body straight"}'::jsonb, '"Dive" makes the child think of head-first entry.', 'Offer "Head first with arms apart" next to the right answer and ask the question again in a new situation.', 'Show a pencil: straight and pointed down, feet first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.CREATI.SWIMMING.SWIMMING.M_CA7_SM_BACK', 'CREA.G7.CREATI.SWIMMING.SWIMMING', 'Says backstroke is swum on the front.', '{"question":"In backstroke the swimmer lies on...","wrong_answer":"The front","correct_answer":"The back"}'::jsonb, 'All strokes learnt so far are on the front.', 'Offer "The front" next to the right answer and ask the question again in a new situation.', 'Float on the back first, then add the arms.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.CREATI.SWIMMING.SWIMMING.M_CA7_SM_SAFETY', 'CREA.G7.CREATI.SWIMMING.SWIMMING', 'Says a learner may swim alone at any time.', '{"question":"When should a learner swim?","wrong_answer":"Alone at any time","correct_answer":"With a lifeguard or teacher"}'::jsonb, 'Confident swimmers feel safe.', 'Offer "Alone at any time" next to the right answer and ask the question again in a new situation.', 'Name what could go wrong alone: cramp, a knock on the head.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.CREATI.SWIMMING.SWIMMING.M_CA7_SM_HEAD_UP_BACK', 'CREA.G7.CREATI.SWIMMING.SWIMMING', 'Lifts the head to look at the feet in backstroke.', '{"question":"In backstroke, where should the head be?","wrong_answer":"lifted to see the feet","correct_answer":"back in the water, ears under, looking up"}'::jsonb, 'The child wants to see where they are going.', 'Offer "lifted to see the feet" next to the right answer and ask the question again in a new context.', 'Float with ears in the water and look at the roof.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.CREATI.KENYAN_INDIGENOUS_GAMES.ROPE_GAMES.M_CA7_RG_NAME', 'CREA.G7.CREATI.KENYAN_INDIGENOUS_GAMES.ROPE_GAMES', 'Names football as a rope game.', '{"question":"Which is a rope game?","wrong_answer":"Football","correct_answer":"Tug of war"}'::jsonb, 'Football is the game the child knows best.', 'Offer "Football" next to the right answer and ask the question again in a new situation.', 'Ask what each game is played with.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.CREATI.KENYAN_INDIGENOUS_GAMES.ROPE_GAMES.M_CA7_RG_BENEFIT', 'CREA.G7.CREATI.KENYAN_INDIGENOUS_GAMES.ROPE_GAMES', 'Says rope games make people less fit.', '{"question":"What do rope games build?","wrong_answer":"Weak muscles","correct_answer":"Fitness and coordination"}'::jsonb, 'The child sees them as play, not exercise.', 'Offer "Weak muscles" next to the right answer and ask the question again in a new situation.', 'Skip for one minute and feel the heartbeat.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.CREATI.KENYAN_INDIGENOUS_GAMES.ROPE_GAMES.M_CA7_RG_SKIP', 'CREA.G7.CREATI.KENYAN_INDIGENOUS_GAMES.ROPE_GAMES', 'Says rope skipping is done sitting down.', '{"question":"How is rope skipping done?","wrong_answer":"Sitting down","correct_answer":"Jumping over the rope"}'::jsonb, 'The child guesses without having skipped.', 'Offer "Sitting down" next to the right answer and ask the question again in a new situation.', 'Skip with the class.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.CREATI.KENYAN_INDIGENOUS_GAMES.ROPE_GAMES.M_CA7_RG_TUG_ARMS', 'CREA.G7.CREATI.KENYAN_INDIGENOUS_GAMES.ROPE_GAMES', 'Thinks tug of war is won only with arm strength.', '{"question":"In tug of war, what gives the most pull?","wrong_answer":"the arms only","correct_answer":"leaning back and pushing with the legs together"}'::jsonb, 'The arms hold the rope, so the child thinks they do the work.', 'Offer "the arms only" next to the right answer and ask the question again in a new context.', 'Pull with arms only, then lean back with the legs; compare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.APPREC.ANALYSIS_OF_CREATIVE_ART.SPORTS_VALUES.M_CA7_SV_CHEAT', 'CREA.G7.APPREC.ANALYSIS_OF_CREATIVE_ART.SPORTS_VALUES', 'Picks fair play as what spoils clean sport, reading the question backwards.', '{"question":"Which spoils clean sport?","wrong_answer":"Fair play","correct_answer":"Cheating"}'::jsonb, 'The child skims for a sports word.', 'Offer "Fair play" next to the right answer and ask the question again in a new situation.', 'Ask: does this make the game fairer or less fair?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.APPREC.ANALYSIS_OF_CREATIVE_ART.SPORTS_VALUES.M_CA7_SV_VALUE', 'CREA.G7.APPREC.ANALYSIS_OF_CREATIVE_ART.SPORTS_VALUES', 'Names cheating as a value of clean sport.', '{"question":"Which is a value of clean sport?","wrong_answer":"Cheating","correct_answer":"Fair play"}'::jsonb, 'The child has seen players gain from cheating.', 'Offer "Cheating" next to the right answer and ask the question again in a new situation.', 'List what happens to a game when everyone cheats.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.APPREC.ANALYSIS_OF_CREATIVE_ART.SPORTS_VALUES.M_CA7_SV_TEAM', 'CREA.G7.APPREC.ANALYSIS_OF_CREATIVE_ART.SPORTS_VALUES', 'Thinks only winning matters in a team game.', '{"question":"What matters in a team game?","wrong_answer":"Only winning","correct_answer":"Teamwork and respect"}'::jsonb, 'Results are what get praised.', 'Offer "Only winning" next to the right answer and ask the question again in a new situation.', 'Discuss a team that lost but played fairly and well together.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.APPREC.ANALYSIS_OF_CREATIVE_ART.SPORTS_VALUES.M_CA7_SV_DRUGS_OK', 'CREA.G7.APPREC.ANALYSIS_OF_CREATIVE_ART.SPORTS_VALUES', 'Thinks taking drugs to run faster is fine if no one finds out.', '{"question":"Is using drugs to win allowed if nobody sees?","wrong_answer":"yes","correct_answer":"no; it is cheating and harms health"}'::jsonb, 'The child thinks a rule only matters if someone checks.', 'Offer "yes" next to the right answer and ask the question again in a new context.', 'Talk about athletes banned for doping.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.APPREC.ANALYSIS_OF_CREATIVE_ART.ANALYSIS.M_CA7_AN_OPINION_ONLY', 'CREA.G7.APPREC.ANALYSIS_OF_CREATIVE_ART.ANALYSIS', 'Analyses a performance only with "I liked it", giving no evidence.', '{"question":"Which is an analysis of a folk song?","wrong_answer":"I liked it","correct_answer":"The soloist and chorus answer each other, showing it is a work song sung in a group"}'::jsonb, 'The child confuses giving an opinion with analysing.', 'Offer "I liked it" next to the right answer and ask the question again in a new context.', 'Ask "what did you hear or see that shows that?" after each point.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.APPREC.ANALYSIS_OF_CREATIVE_ART.ANALYSIS.M_CA7_AN_THEME_PLOT', 'CREA.G7.APPREC.ANALYSIS_OF_CREATIVE_ART.ANALYSIS', 'Gives the events of the story when asked for its theme.', '{"question":"What is the theme of the story we watched?","wrong_answer":"the hare tricked the hyena and ran away","correct_answer":"cleverness can beat strength"}'::jsonb, 'The child retells instead of naming the idea.', 'Offer "the hare tricked the hyena and ran away" next to the right answer and ask the question again in a new context.', 'Ask "what is the story teaching?" after retelling.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.APPREC.ANALYSIS_OF_CREATIVE_ART.ANALYSIS.M_CA7_AN_TYPE_FROM_TUNE', 'CREA.G7.APPREC.ANALYSIS_OF_CREATIVE_ART.ANALYSIS', 'Names a folk song''s type only from how fast it is.', '{"question":"A fast song is sung while winnowing. What type is it?","wrong_answer":"a dance song, because it is fast","correct_answer":"a work song"}'::jsonb, 'The child uses tempo alone.', 'Offer "a dance song, because it is fast" next to the right answer and ask the question again in a new context.', 'Look at the occasion and the words first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G7.APPREC.ANALYSIS_OF_CREATIVE_ART.ANALYSIS.M_CA7_AN_TECHNIQUE_CONTENT', 'CREA.G7.APPREC.ANALYSIS_OF_CREATIVE_ART.ANALYSIS', 'Names what the story is about when asked for a storytelling technique.', '{"question":"Name a technique the storyteller used.","wrong_answer":"a story about a lion","correct_answer":"changing her voice for each animal"}'::jsonb, 'The child mixes the content with how it was told.', 'Offer "a story about a lion" next to the right answer and ask the question again in a new context.', 'Ask "how did she tell it?" not "what was it about?".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
